css:
:root {
  /* primitive — colour */
  --bg: oklch(99% 0.002 240);
  --surface: oklch(100% 0 0);
  --fg: oklch(18% 0.012 250);
  --muted: oklch(54% 0.012 250);
  --border: oklch(92% 0.005 250);
  --accent: oklch(58% 0.18 255);
  --warn: oklch(72% 0.15 75);

  /* primitive — spacing */
  --space-0-5: 2px; --space-1: 4px; --space-1-5: 6px; --space-2: 8px;
  --space-2-5: 10px; --space-3: 12px; --space-3-5: 14px; --space-4: 16px;
  --space-4-5: 18px; --space-5: 20px; --space-6: 24px; --space-7: 28px;
  --space-8: 32px; --space-9: 36px; --space-10: 40px; --space-11: 44px;
  --space-12: 48px; --space-13: 52px; --space-14: 56px; --space-16: 64px;
  --space-18: 72px; --space-27: 108px; --space-28: 112px;

  /* primitive — type */
  --fs-2xs: 10px; --fs-xs: 11px; --fs-sm: 12px; --fs-md: 13px;
  --fs-base: 14px; --fs-lg: 15px; --fs-xl: 17px; --fs-2xl: 20px;
  --fs-3xl: 22px; --fs-5xl: 26px; --fs-7xl: 40px;
  --fw-medium: 500; --fw-semibold: 600; --fw-bold: 700;
  --lh-tight: 1; --lh-snug: 1.2; --lh-normal: 1.3; --lh-relaxed: 1.5;
  --tracking-tighter: -0.03em; --tracking-tight: -0.02em; --tracking-snug: -0.015em;
  --tracking-normal: -0.005em; --tracking-wide: .02em; --tracking-wider: .06em; --tracking-widest: .07em;

  /* primitive — radius / icon / border / shadow / motion / z-index */
  --radius-xs: 6px; --radius-sm: 8px; --radius-md: 10px; --radius-lg: 12px; --radius-pill: 999px;
  --icon-sm: 15px; --icon-md: 16px; --icon-lg: 18px; --icon-xl: 22px;
  --border-w: 1px; --border-w-2: 2px;
  --shadow-xs: 0 1px 2px color-mix(in oklch, var(--fg) 8%, transparent);
  --shadow-md: 0 1px 2px color-mix(in oklch, var(--fg) 6%, transparent), 0 12px 32px -12px color-mix(in oklch, var(--fg) 12%, transparent);
  --dur-fast: .15s; --dur-snap: .05s; --ease-standard: ease;
  --z-appbar: 10; --z-sticky: 9;

  /* primitive — fonts */
  --font-display: -apple-system, BlinkMacSystemFont, 'SF Pro Display', system-ui, sans-serif;
  --font-body: -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;
  --font-mono: ui-monospace, 'JetBrains Mono', 'SF Mono', Menlo, monospace;

  /* semantic — colour aliases */
  --accent-soft: color-mix(in oklch, var(--accent) 14%, transparent);
  --accent-ink: color-mix(in oklch, var(--accent) 84%, black);
  --fg-soft: color-mix(in oklch, var(--fg) 6%, transparent);
  --fg-softer: color-mix(in oklch, var(--fg) 3%, transparent);
  --muted-text: color-mix(in oklch, var(--muted) 80%, var(--fg)); /* >=4.5:1 on --bg for small text */
  --border-strong: color-mix(in oklch, var(--border) 70%, var(--fg));
  --warn-soft: color-mix(in oklch, var(--warn) 18%, transparent);
  --warn-ink: color-mix(in oklch, var(--warn) 55%, black);
  --fs-heading: var(--fs-3xl);
  --fs-body: var(--fs-base);
  --fs-caption: var(--fs-sm);

  /* component — named intent */
  --control-sm: var(--space-9);
  --control-md: var(--space-11);
  --appbar-h: var(--space-14);
  --pane-customize-w: 520px;
  --paper-w: 680;
  --paper-max-w: 760px;
  --dropzone-min-h: var(--space-27);
  --invoice-logo-max-w: 200px;
  --invoice-totals-w: 300px;
  --sticky-footer-clearance: 76px;
}
